def _expand_query_with_vocabulary(self, query: str) -> str:
    """Expand query terms using vocabulary mappings (Step 0.5 in recall pipeline).

    Resolves operator vocabulary to find additional search terms.
    Example: "working copy" → "working copy worktree git worktree"
    """
    try:
        # Check individual terms and bigrams
        words = query.lower().split()
        expansion_terms = []

        # Check bigrams first (more specific)
        checked_bigrams = set()
        for i in range(len(words) - 1):
            bigram = f'{words[i]} {words[i+1]}'
            checked_bigrams.add(bigram)
            result = self.resolve_vocabulary(bigram)
            if result and not result.get('ambiguous'):
                # Parse maps_to from content: '"term" → X, Y'
                content = result.get('content', '')
                if '\u2192' in content:
                    mapped = content.split('\u2192', 1)[1].strip()
                    for t in mapped.split(','):
                        t = t.strip()
                        if t and t.lower() not in query.lower():
                            expansion_terms.append(t)

        # Check individual words (skip if part of a matched bigram)
        for word in words:
            if len(word) <= 2:
                continue
            # Skip if this word was part of a matched bigram
            if any(word in bg for bg in checked_bigrams if self.resolve_vocabulary(bg)):
                continue
            result = self.resolve_vocabulary(word)
            if result and not result.get('ambiguous'):
                content = result.get('content', '')
                if '\u2192' in content:
                    mapped = content.split('\u2192', 1)[1].strip()
                    for t in mapped.split(','):
                        t = t.strip()
                        if t and t.lower() not in query.lower():
                            expansion_terms.append(t)

        # Cap expansion
        expansion_terms = expansion_terms[:VOCAB_EXPANSION_MAX]

        if expansion_terms:
            # Log expansion via recall_log (use returned_ids for expansion info)
            try:
                session_id = getattr(self, 'session_id', 'unknown')
                self.logs_conn.execute(
                    "INSERT INTO recall_log (session_id, query, returned_ids, returned_count, created_at) VALUES (?, ?, ?, ?, ?)",
                    (session_id, query, 'vocab_expansion: ' + ', '.join(expansion_terms), len(expansion_terms), self.now())
                )
                self.logs_conn.commit()
            except Exception:
                pass  # Non-critical logging

            return query + ' ' + ' '.join(expansion_terms)

                            if term in _high_conf:
                                try:
                                    brain.learn_vocabulary(
                                        term=term,
                                        maps_to=["detected in: '%s'" % user_message[:80]],
                                        context="auto-detected")
                                except Exception:
                                    # If learn_vocabulary fails (validation, etc), fall through to gap
                                    gaps.append({"term": term, "message_preview": user_message[:80]})
                            else:
                                gaps.append({"term": term, "message_preview": user_message[:80]})
                    gaps = gaps[-20:]
                    brain.set_config("vocabulary_gaps", json.dumps(gaps))
        except Exception:
            pass

    # ── Encoding heartbeat with rotating checkpoints ──
    output = ""
    try:
        brain.record_message()
        nudge = brain.get_encoding_heartbeat()
        if nudge:
            msg = nudge.get("message", "")

            # Get and rotate checkpoint
            try:
                idx = int(brain.get_config("checkpoint_index", "0"))
            except Exception:
                idx = 0
            focus = CHECKPOINT_CYCLE[idx % len(CHECKPOINT_CYCLE)]
            next_idx = str((idx + 1) % len(CHECKPOINT_CYCLE))
            try:
                brain.set_config("checkpoint_index", next_idx)
            except Exception:
                pass

            # Session encoding stats
            try:
                node_count = brain.conn.execute(
                    "SELECT COUNT(*) FROM nodes WHERE created_at > datetime('now', '-2 hours')"
                ).fetchone()[0]
                uncert_count = brain.conn.execute(
                    "SELECT COUNT(*) FROM nodes WHERE type = 'uncertainty' AND created_at > datetime('now', '-2 hours')"
                ).fetchone()[0]
                connect_count = brain.conn.execute(
                    "SELECT COUNT(*) FROM edges WHERE created_at > datetime('now', '-2 hours')"
                ).fetchone()[0]
                stats = "Session stats: %d nodes, %d uncertainties, %d connections." % (
                    node_count, uncert_count, connect_count)
            except Exception:
                stats = ""

            checkpoint_lines = ["[BRAIN] ENCODING CHECKPOINT: " + msg]
            if stats:
                checkpoint_lines.append(stats)
            checkpoint_lines.append(focus)
            checkpoint_lines.append("[/BRAIN]")
            checkpoint_text = "\n".join(checkpoint_lines)

            if is_user_prompt:
                output = "\n" + checkpoint_text + "\n"
            else:
                # Stop event — store as pending (invisible)
                _store_pending(brain, checkpoint_text)
    except Exception:
        pass

    brain.save()
    return {"output": output}


def hook_idle_maintenance(brain, args, graph_changes):
    """Idle maintenance — dream, consolidate, heal, tune, reflect.

    Fires on Notification(idle_prompt). Output stored as pending message.
    """
    output = []

    # 1. Dream
    try:
        dream_result = brain.dream()
        dream_count = dream_result.get("count", 0)
        if dream_count > 0:
            output.append("DREAM: %d dream(s) generated" % dream_count)
            for d in dream_result.get("dreams", [])[:2]:
                output.append("  - " + d.get("title", "untitled"))
            graph_changes.append("DREAM: %d new dream node(s)" % dream_count)
    except Exception as e:
        output.append("DREAM ERROR: %s" % e)

if candidates:
    try:
        vocab_rows = brain.conn.execute(
            "SELECT LOWER(title), LOWER(content) FROM nodes WHERE type = ? AND archived = 0",
            ("vocabulary",),
        ).fetchall()
    except Exception:
        vocab_rows = []

    known_terms = set()
    for title, content in vocab_rows:
        if " \u2192 " in title:
            known_terms.add(title.split(" \u2192 ")[0].strip())
        elif " -> " in title:
            known_terms.add(title.split(" -> ")[0].strip())
        else:
            known_terms.add(title.strip())

    try:
        all_titles = brain.conn.execute(
            "SELECT LOWER(title) FROM nodes WHERE archived = 0"
        ).fetchall()
        title_set = {r[0] for r in all_titles}
    except Exception:
        title_set = set()

    unmapped = []
    for term in candidates:
        if term in known_terms:
            continue
        if term in title_set:
            continue
        if any(term in kt or kt in term for kt in known_terms):
            continue
        words = term.split()
        if len(words) == 1 and any(term in t for t in title_set):
            continue
        unmapped.append(term)

    if unmapped:
        existing = brain.get_config("vocabulary_gaps", "[]")
        try:
            gaps = json.loads(existing)
        except Exception:
            gaps = []
        existing_terms = {g.get("term") if isinstance(g, dict) else g for g in gaps}

        # Auto-encode high-confidence terms immediately.
        # Backtick, acronym, and capitalized terms are almost certainly real.
        # Store with message context — thin-node enrichment will ask Tom later.
        _high_conf = set(t.strip() for t in backtick + acronyms + capitalized)
        for term in unmapped[:5]:
            if term not in existing_terms:
                if term in _high_conf:
                    try:
                        brain.learn_vocabulary(
                            term=term,
                            maps_to=["detected in: '%s'" % user_message[:80]],
                            context="auto-detected")
                    except Exception:
                        # If learn_vocabulary fails (validation, etc), fall through to gap
                        gaps.append({"term": term, "message_preview": user_message[:80]})
                else:
                    gaps.append({"term": term, "message_preview": user_message[:80]})

