CREATE TABLE edges (
  source_id TEXT NOT NULL,
  target_id TEXT NOT NULL,
  weight REAL DEFAULT 0.5,         -- connection strength (0-1)
  relation TEXT DEFAULT 'related', -- semantic label
  co_access_count INTEGER DEFAULT 1,
  stability REAL DEFAULT 1.0,
  last_strengthened TEXT,
  created_at TEXT, edge_type TEXT DEFAULT 'related', decay_rate REAL DEFAULT NULL, description TEXT DEFAULT '',
  PRIMARY KEY (source_id, target_id),
  FOREIGN KEY (source_id) REFERENCES nodes(id) ON DELETE CASCADE,
  FOREIGN KEY (target_id) REFERENCES nodes(id) ON DELETE CASCADE
);
CREATE INDEX idx_edges_source ON edges(source_id);
CREATE INDEX idx_edges_target ON edges(target_id);
CREATE INDEX idx_edges_weight ON edges(weight);
CREATE INDEX idx_edges_type ON edges(edge_type);

CREATE TABLE node_embeddings (
        node_id TEXT PRIMARY KEY,
        embedding BLOB NOT NULL,
        model TEXT NOT NULL DEFAULT 'bge-m3',
        created_at TEXT NOT NULL,
        FOREIGN KEY (node_id) REFERENCES nodes(id) ON DELETE CASCADE
      );
CREATE INDEX idx_node_embeddings_model ON node_embeddings(model);

