def _build_enrichment_prompt(self, node_id: str, title: str,
                              content: Optional[str] = None) -> Optional[str]:
    """Build the V5 structured enrichment prompt for a node.

    Finds neighbors via edges, formats them, and returns the prompt
    for Claude (or local LLM) to fill in.

    Returns None if node has no neighbors (nothing to anchor to).
    """
    try:
        graph_dal = GraphDAL(self.conn)
        neighbors = graph_dal.get_neighbors_with_context(
            node_id, limit=ENRICHMENT_NEIGHBOR_COUNT
        )
        if not neighbors:
            return None

        neighbor_lines = []
        for nb in neighbors:
            kw = nb.get('keywords', '') or ''
            kw_short = ', '.join(kw.split()[:5]) if kw else 'none'
            neighbor_lines.append(
                f"- {nb['title'][:80]} ({nb['type']}, keywords: {kw_short})"
            )

        content_preview = (content or '')[:200]
        prompt = ENRICHMENT_PROMPT_TEMPLATE.format(
            neighbors='\n'.join(neighbor_lines),
            title=title,
            content=content_preview,
        )
        return prompt
    except Exception as e:
        print(f'[brain] _build_enrichment_prompt failed: {e}', file=sys.stderr)
        return None

def store_enrichments(self, node_id: str, question: Optional[str] = None,
                      anchor: Optional[str] = None, bridge: Optional[str] = None,
                      keywords: Optional[str] = None) -> Dict[str, Any]:
    """Store enrichment vectors for a node (called after Claude fills in the prompt).

    Each non-None enrichment text is embedded and stored in node_enrichments.
    Returns count of enrichments stored and any errors.
    """
    enrichment_dal = EnrichmentDAL(self.conn)
    stored = 0
    errors = []

    enrichments = {
        'question': question,
        'anchor': anchor,
        'bridge': bridge,
        'keywords': keywords,
    }

    for vtype, text in enrichments.items():
        if not text or not text.strip():
            continue
        text = text.strip()
        try:
            blob = None
            if embedder.is_ready():
                blob = embedder.embed(text)
            enrichment_dal.store(node_id, vtype, text, blob,
                                model=embedder.stats.get('model_name', 'unknown') if embedder.is_ready() else 'none')
            stored += 1
        except Exception as e:
            errors.append(f'{vtype}: {str(e)[:100]}')
            print(f'[brain] Enrichment embed failed for {node_id}/{vtype}: {e}', file=sys.stderr)

    return {
        'node_id': node_id,
        'enrichments_stored': stored,
        'errors': errors if errors else None,
    }

def get_enrichment_coverage(self) -> Dict[str, Any]:
    """Get enrichment coverage stats."""
    try:
        enrichment_dal = EnrichmentDAL(self.conn)
        return enrichment_dal.get_coverage_stats()
    except Exception as e:
        return {'error': str(e)}

def enrich_keywords(self, node_id: str) -> Optional[str]:
    """
    Enrich keywords on a node from its content.
    Used by health check for frequently-missed nodes.
    """
    try:

        t.strip().lower() for t in
        re.findall(r"\bthe\s+([\w][\w\s-]{2,25})\b", user_message, re.IGNORECASE)
    )
    candidates.update(
        t.strip().lower() for t in
        re.findall(r"\b([\w]+-[\w]+(?:-[\w]+)?)\b", user_message)
        if len(t) > 4
    )
    for term in candidates:
        resolved = brain.resolve_vocabulary(term)
        if resolved:
            if resolved.get("ambiguous"):
                for m in resolved.get("mappings", []):
                    expansions.append(m.get("content", ""))
            else:
                expansions.append(resolved.get("content", ""))
except Exception:
    pass

enriched = user_message[:500]
if expansions:
    enriched += " " + " ".join(expansions)[:200]

# Recall
try:
    result = brain.recall_with_embeddings(query=enriched, limit=8)
except Exception:
    result = brain.recall(query=enriched, limit=8)

results = result.get("results", [])

# ── Precision: log recall through the precision module ──
# Previously, logging was buried inside recall_with_embeddings() via _log_recall().
# Now the hook calls precision.log_recall() explicitly, storing full context
# (titles, snippets, embeddings_used flag) for future evaluation.
if results:
    try:
        precision = _get_precision(brain)
        recalled_titles = {r.get("id"): r.get("title", "")[:100] for r in results}
        recalled_snippets = {r.get("id"): (r.get("content") or "")[:150] for r in results}
        embeddings_used = result.get("_recall_mode") != "keyword_only_DEGRADED"
        recall_log_id = precision.log_recall(
            session_id=session_id,
            query=enriched[:500],
            returned_ids=[r.get("id") for r in results],
            recalled_titles=recalled_titles,
            recalled_snippets=recalled_snippets,
            embeddings_used=embeddings_used,
        )
        # Table-driven: row IS the state (Stage 1: LOGGED). No config key needed.
        # Fallback config set for backward compat if DAL not available.
        if not getattr(brain, '_logs_dal', None):
            brain.set_config("last_recall_log_id", str(recall_log_id))
    except Exception as e:
        brain._log_error('precision_log_recall', e, 'query=%s' % enriched[:100])

# Segment boundary detection
segment_note = None
try:
    query_emb = result.get("_query_embedding")
    if query_emb:
        seg = brain.check_segment_boundary(query_emb)
        if seg.get("is_boundary"):
            segment_note = "--- CONTEXT SHIFT (segment %d, sim=%.2f) ---" % (
                seg["segment_id"], seg["similarity"])
        for r in results:
            brain.add_to_segment(r.get("id", ""))
except Exception:
    pass

# Drain pending messages
pending_messages = _drain_pending(brain)

# Drain debug logs (hook_debug entries from brain_logs.db)
debug_messages = _drain_debug_logs(brain)

# Drain graph changes
recent_graph_changes = _drain_graph_changes(graph_changes)

# Awareness heartbeat — urgent signals from consciousness layer
urgent_signals = []
try:
    urgent_signals = brain.get_urgent_signals()
except Exception:
    pass

if not results and not pending_messages and not urgent_signals and not recent_graph_changes and not debug_messages:
    brain.save()
    return {"json": {"decision": "approve"}}

# Priming check
priming_note = None
try:
